\subsection*{Step-by-Step Solution:}

\subsubsection*{Finding the Derivative:}
\begin{equation}
y = \tan x - \frac{2}{\cos x}
\end{equation}
\begin{align*}
y' &= \sqrt{3} \sec^2 x + \frac{2}{\cos^2 x} \\
     &= \frac{(\sqrt{3}\cos x + 1)^2}{\cos^2 x} \geq 0
\end{align*}
This implies that \( y' \geq 0 \) in \( \left( -\frac{\pi}{2}, \frac{\pi}{2} \right) \).

\subsubsection*{Confirming the Critical Point:}
\begin{align*}
y' &= 0 \quad \text{when} \quad (\sqrt{3}\cos x + 1)^2 = 0 \\
     &\implies \cos x = -\frac{1}{\sqrt{3}}
\end{align*}
