\end{align*}
Since \( y'' > 0 \) at \( x = \frac{\pi}{4} \), \( y \left(x\right) \) is indeed the maximum value.

\subsubsection*{Calculating the Maximum Value:}
\begin{align*}
y_{\text{yt}} \left( \frac{\pi}{4} \right) &= \tan \left( \frac{\pi}{4} \right) - \frac{1}{\cos \frac{\pi}{4}} \\
